import{_ as t,o as a,c as r,a0 as o}from"./chunks/framework.C5ukcOJf.js";const l=JSON.parse('{"title":"OAuth2","description":"","frontmatter":{},"headers":[],"relativePath":"api/auth-foundation/OAuth2/index.md","filePath":"api/auth-foundation/OAuth2/index.md"}'),n={name:"api/auth-foundation/OAuth2/index.md"};function i(d,e,s,h,c,f){return a(),r("div",null,[...e[0]||(e[0]=[o('<p><a href="./..">@okta/auth-foundation</a> / OAuth2</p><h1 id="oauth2" tabindex="-1">OAuth2 <a class="header-anchor" href="#oauth2" aria-label="Permalink to &quot;OAuth2&quot;">​</a></h1><h2 id="dpop" tabindex="-1">DPoP <a class="header-anchor" href="#dpop" aria-label="Permalink to &quot;DPoP&quot;">​</a></h2><p>Defined in <a href="https://datatracker.ietf.org/doc/html/rfc9449" target="_blank" rel="noreferrer">RFC 9449</a>, Demonstrating Proof of Possession (DPoP) is a <strong>significant</strong> security improvement which binds OAuth2 tokens to a private/public key pair. The private key is only accessible to the requesting client. Any resource server (or <code>refresh_token</code> grant) requests made with bound tokens are required to be signed by the private key. Any requests which attempt to use bound tokens without a valid signature will be rejected. This results in a significantly improved security posture against token theft-based attacks, as tokens are nearly useless without access to the private key they are bound to.</p><table tabindex="0"><thead><tr><th>Interface</th><th>Description</th></tr></thead><tbody><tr><td><a href="./interfaces/DPoPSigningAuthority">DPoPSigningAuthority</a></td><td>A Platform-level singleton for performing <code>DPoP</code> operations. The <a href="./interfaces/DPoPSigningAuthority">DPoPSigningAuthority</a> is reasonable for mangaging <code>DPoP</code> key pairs and generate <code>DPoP</code> proofs for outgoing <a href="https://developer.mozilla.org/docs/Web/API/Request" target="_blank" rel="noreferrer">Request</a>s</td></tr><tr><td><a href="./interfaces/DPoPNonceCache">DPoPNonceCache</a></td><td>&gt; The intent is that clients need to keep only one nonce value and servers need to keep a window of recent nonces.</td></tr><tr><td><a href="./interfaces/DPoPStorage">DPoPStorage</a></td><td>A simple storage interface for <code>DPoP</code> key pairs</td></tr><tr><td><a href="./interfaces/DPoPClaims">DPoPClaims</a></td><td><code>JWT</code> claims associated with a <code>DPoP</code> proof</td></tr><tr><td><a href="./interfaces/DPoPHeaders">DPoPHeaders</a></td><td><code>JWT</code> header parameters for a <code>DPoP</code> proof</td></tr><tr><td><a href="./interfaces/DPoPProofParams">DPoPProofParams</a></td><td>Parameters required to generate a <code>DPoP</code> proof</td></tr></tbody></table><h2 id="interfaces" tabindex="-1">Interfaces <a class="header-anchor" href="#interfaces" aria-label="Permalink to &quot;Interfaces&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Interface</th><th>Description</th></tr></thead><tbody><tr><td><a href="./interfaces/APIClientConfiguration">APIClientConfiguration</a></td><td>-</td></tr><tr><td><a href="./interfaces/OpenIdConfiguration">OpenIdConfiguration</a></td><td>Interface defining the response payload from <code>/.well-known/openid-configuration</code></td></tr></tbody></table><h2 id="oauth2client" tabindex="-1">OAuth2Client <a class="header-anchor" href="#oauth2client" aria-label="Permalink to &quot;OAuth2Client&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><a href="./OAuth2Request/">OAuth2Request</a></td><td>A builder class for <a href="https://developer.mozilla.org/docs/Web/API/Request" target="_blank" rel="noreferrer">Request</a> instances representing a OAuth2 endpoint request</td></tr><tr><td><a href="./OAuth2Request/">OAuth2Request</a></td><td>-</td></tr><tr><td><a href="./OAuth2Client/">OAuth2Client</a></td><td>-</td></tr><tr><td><a href="./OAuth2Client/">OAuth2Client</a></td><td>-</td></tr><tr><td><a href="./type-aliases/OAuth2ClientOptions">OAuth2ClientOptions</a></td><td>Configuration options for <a href="./OAuth2Client/">OAuth2Client</a></td></tr><tr><td><a href="./interfaces/ConfigurationParams">ConfigurationParams</a></td><td>Options to provide to <a href="./classes/Configuration">Configuration</a> at instantiation</td></tr><tr><td><a href="./classes/Configuration">Configuration</a></td><td>Options to customize the behavior of a <a href="./OAuth2Client/">OAuth2Client</a> instance</td></tr></tbody></table><h2 id="pkce" tabindex="-1">PKCE <a class="header-anchor" href="#pkce" aria-label="Permalink to &quot;PKCE&quot;">​</a></h2><p>Defined in <a href="https://datatracker.ietf.org/doc/html/rfc7636" target="_blank" rel="noreferrer">RFC 7636</a>, Proof Key for Code Exchange (PKCE) helps protect authorization codes (returned as the query paramter <code>code</code>) when performing <code>Authorization Code Flow</code>. The client generates a cryptographically-random string and hashes it (the challenge). Both the challenge andhashing algorithm are provided to the authorization server as parameters to <code>/authorize</code>. When the client receives the <code>code</code> from the authorization server, it must provide a <code>code_verifier</code>, the orginial pre-hashed string when the <code>code</code> is exchanged for tokens. The token exchange will fail if an incorrect verifier is provided.</p><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><a href="./type-aliases/PKCE">PKCE</a></td><td>Defines the properties returned by <a href="./namespaces/PKCE/functions/generate">PKCE.generate</a></td></tr><tr><td><a href="./namespaces/PKCE/">PKCE</a></td><td>-</td></tr></tbody></table><h2 id="types" tabindex="-1">Types <a class="header-anchor" href="#types" aria-label="Permalink to &quot;Types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Description</th></tr></thead><tbody><tr><td><a href="./interfaces/OAuth2ErrorResponse">OAuth2ErrorResponse</a></td><td>JSON format of an error response returned by authorization server</td></tr><tr><td><a href="./functions/isOAuth2ErrorResponse">isOAuth2ErrorResponse</a></td><td>Predicate for <a href="./interfaces/OAuth2ErrorResponse">OAuth2ErrorResponse</a></td></tr><tr><td><a href="./functions/isOpenIdConfiguration">isOpenIdConfiguration</a></td><td>Type predicate for <a href="./interfaces/OpenIdConfiguration">OpenIdConfiguration</a></td></tr><tr><td><a href="./functions/isJWK">isJWK</a></td><td>Type predicate for <a href="./../Core/interfaces/JWK">JWK</a></td></tr><tr><td><a href="./functions/isJWKS">isJWKS</a></td><td>Type predicate for <a href="./../Core/type-aliases/JWKS">JWKS</a></td></tr><tr><td><a href="./type-aliases/OAuth2Params">OAuth2Params</a></td><td>Parameters needed to define an OAuth2 flow</td></tr><tr><td><a href="./type-aliases/GrantType">GrantType</a></td><td>Possible values of <code>grant_type</code> for a <code>/token</code> request</td></tr><tr><td><a href="./type-aliases/TokenType">TokenType</a></td><td>Possible values of <code>token_type</code> from a <code>/token</code> response</td></tr><tr><td><a href="./type-aliases/ClientAuthentication">ClientAuthentication</a></td><td>Possible values of <a href="./classes/Configuration#authentication">OAuth2.Configuration.authentication</a> property. Determines how the <a href="./OAuth2Client/">OAuth2Client</a> will sign OAuth2 requests</td></tr><tr><td><a href="./type-aliases/AcrValues">AcrValues</a></td><td>Possible types of <code>acr_values</code> for OAuth2 requests</td></tr><tr><td><a href="./type-aliases/OktaAcrValues">OktaAcrValues</a></td><td>Possible <code>acr_values</code> of Okta authorization servers</td></tr></tbody></table>',14)])])}const p=t(n,[["render",i]]);export{l as __pageData,p as default};
